section.codeblock:
let $referenceReport := doc('file:///path/to/reports/reference-report.xml')
let $referenceHashes :=
    map:merge(
      for $f in $referenceReport//file
      return map:entry(string($f/@path), string($f/@hash))
    )
for $file in collection('file:///path/to/reports/')//file
let $path := string($file/@path)
let $refHash := map:get($referenceHashes, $path)
let $report := $file/ancestor::fileHashReport
where exists($refHash) and string($file/@hash) != $refHash
return
  <mismatch path="{$path}"
            report="{base-uri(root($file))}"
            user="{$report/meta[@name='userName']/@content}"
            referenceHash="{$refHash}" actualHash="{$file/@hash}"/>
